ht:800;cursor:pointer}.upload input{display:none}.save{margin-top:18px;width:100%;border:0;border-radius:11px;padding:14px;color:#fff;background:linear-gradient(100deg,#079bcc,#10b974);font-weight:850;box-shadow:0 10px 22px rgba(16,185,116,.2)}.preview-panel{padding:18px;border-radius:15px;background:#edf7fb}.preview-panel h2{margin:0 0 4px;font-size:17px}.preview-panel p{color:#657e90;font-size:11px}.sheet{display:flex;justify-content:center;padding:18px;margin-top:14px;border-radius:12px;background:#fff;overflow:auto}.label-preview{position:relative;overflow:hidden;box-sizing:border-box;border:2px solid #111;border-radius:8px;padding:5px;background:#fff;color:#000;font:700 9px Arial}.label-preview img{display:block;width:40%;height:22%;object-fit:contain}.preview-address{position:absolute;right:5px;top:4px;font-size:7px}.preview-price{position:absolute;right:5px;top:26px;text-align:center;font-size:8px}.preview-price b{display:block;border:1px solid #111;padding:3px;font-size:14px}.rows{margin-top:5px}.rows div{display:flex;gap:4px;line-height:12px}.rows strong{width:48px;color:#fff;background:#000;padding:0 3px}.fake-code{height:25%;margin:5px 12px 0;background:repeating-linear-gradient(90deg,#000 0 2px,#fff 2px 4px)}.hint{margin-top:14px;padding:12px;border-radius:10px;background:#fff5d9;color:#805600;font-size:11px}.toast-tag{position:fixed;right:22px;bottom:22px;z-index:9999;padding:14px 18px;border-radius:10px;background:#073653;color:#fff;opacity:0;transform:translateY(80px);transition:.25s}.toast-tag.show{opacity:1;transform:none}.toast-tag.error{background:#bd293b}@media(max-width:900px){.tag-card{grid-template-columns:1fr}.tag-form-grid,.options{grid-template-columns:1fr}.preview-panel{order:-1}}
