</form></main><div class="toast-tag" id="tagToast"></div>
<script>
(function(){var a=document.getElementById('ancho'),h=document.getElementById('alto'),p=document.getElementById('labelPreview'),color=document.getElementById('showColor'),genero=document.getElementById('showGenero'),botapie=document.getElementById('showBotapie'),logoInput=document.getElementById('logoInput'),logoPreview=document.getElementById('logoPreview'),miniLogo=document.getElementById('miniLogo'),form=document.getElementById('tagForm'),save=document.getElementById('saveTag');function draw(){var scale=Math.min(5.5,360/Math.max(25,+a.value));p.style.width=(+a.value*scale)+'px';p.style.height=(+h.value*scale)+'px';document.getElementById('rowColor').style.display=color.checked?'flex':'none';document.getElementById('rowGenero').style.display=genero.checked?'flex':'none';document.getElementById('rowBotapie').style.display=botapie.checked?'flex':'none';}document.querySelectorAll('.preset').forEach(function(b){b.onclick=function(){a.value=this.dataset.w;h.value=this.dataset.h;draw();};});[a,h,color,genero,botapie].forEach(function(x){x.addEventListener('input',draw);});logoInput.onchange=function(){if(this.files[0]){var u=URL.createObjectURL(this.files[0]);logoPreview.src=u;miniLogo.src=u;}};draw();form.onsubmit=function(e){e.preventDefault();save.disabled=true;var t=document.getElementById('tagToast');fetch('/controllers/EtiquetasConfigGuardar.php',{method:'POST',body:new FormData(form),credentials:'same-origin'}).then(function(r){return r.json().then(function(d){return {ok:r.ok,d:d};});}).then(function(x){t.textContent=x.d.message;t.className='toast-tag show'+(x.ok?'':' error');if(x.ok)setTimeout(function(){location.reload();},900);}).catch(function(){t.textContent='No se pudo guardar.';t.className='toast-tag show error';}).finally(function(){save.disabled=false;setTimeout(function(){t.classList.remove('show');},4000);});};})();
</script></body></html>
